//! SettingsAccount JSON token spans. Transient bounded tree; no reserialization or unknown-value coercion.
use crate::Error;
use std::{collections::HashSet,ops::Range};
pub const MAX_ACCOUNT:usize=2_000_000;
const MAX_NODES:usize=100_000;
#[derive(Debug,Clone,PartialEq)]pub struct AccountAchievement{pub guid:[u8;16],pub complete:bool,pub current:f64,pub completed:Option<String>,pub fields:[Range<usize>;3]}
#[derive(Debug,Clone,PartialEq)]pub struct AccountCounter{pub guid:[u8;16],pub current:f64,pub field:Range<usize>}
#[derive(Debug)]pub struct AccountIndex{pub achievements:Vec<AccountAchievement>,pub counters:Vec<AccountCounter>}
struct Node{kind:Kind,span:Range<usize>}
enum Kind{Null,Bool(bool),Str(String),Num,Array,Object(Vec<(String,Node)>)}
impl Node{fn obj(&self)->Result<&[(String,Node)],Error>{match &self.kind{Kind::Object(o)=>Ok(o),_=>Err(Error::Schema)}}fn field(&self,k:&str)->Result<&Node,Error>{self.obj()?.iter().find(|(key,_)|key==k).map(|(_,v)|v).ok_or(Error::Schema)}fn number(&self,raw:&str)->Result<f64,Error>{if !matches!(&self.kind,Kind::Num){return Err(Error::Schema)}let n: f64=raw[self.span.clone()].parse().map_err(|_|Error::Schema)?;if !n.is_finite(){return Err(Error::Schema)}Ok(n)}}
struct Parser<'a>{s:&'a str,p:usize,n:usize}
impl<'a> Parser<'a>{fn peek(&self)->Option<u8>{self.s.as_bytes().get(self.p).copied()}fn ws(&mut self){while matches!(self.peek(),Some(b' '|b'\n'|b'\r'|b'\t')){self.p+=1}}fn eat(&mut self,b:u8)->Result<(),Error>{if self.peek()!=Some(b){return Err(Error::Schema)}self.p+=1;Ok(())}fn literal(&mut self,s:&str)->Result<(),Error>{if self.s.as_bytes().get(self.p..self.p+s.len())!=Some(s.as_bytes()){return Err(Error::Schema)}self.p+=s.len();Ok(())}fn hex4(&mut self)->Result<u16,Error>{let mut v=0;for _ in 0..4{let b=self.peek().ok_or(Error::Truncated)?;self.p+=1;v=v*16+(b as char).to_digit(16).ok_or(Error::Schema)? as u16;}Ok(v)}
 fn string(&mut self)->Result<String,Error>{self.eat(b'"')?;let mut s=String::new();loop{match self.peek().ok_or(Error::Truncated)?{b'"'=>{self.p+=1;return Ok(s)},b'\\'=>{self.p+=1;let b=self.peek().ok_or(Error::Truncated)?;self.p+=1;let c=match b{b'"'=>'"',b'\\'=>'\\',b'/'=>'/',b'b'=>'\u{8}',b'f'=>'\u{c}',b'n'=>'\n',b'r'=>'\r',b't'=>'\t',b'u'=>{let hi=self.hex4()?;let val=if (0xd800..=0xdbff).contains(&hi){self.literal("\\u")?;let lo=self.hex4()?;if !(0xdc00..=0xdfff).contains(&lo){return Err(Error::Schema)}0x10000+(((hi as u32)-0xd800)<<10)+(lo as u32-0xdc00)}else{hi as u32};char::from_u32(val).ok_or(Error::Schema)?},_=>return Err(Error::Schema)};s.push(c)},0..=31=>return Err(Error::Schema),_=>{let c=self.s.get(self.p..).ok_or(Error::Schema)?.chars().next().ok_or(Error::Truncated)?;self.p+=c.len_utf8();s.push(c)}}}}
 fn digits(&mut self)->Result<(),Error>{let a=self.p;while matches!(self.peek(),Some(b'0'..=b'9')){self.p+=1}if self.p==a{Err(Error::Schema)}else{Ok(())}}
 fn number(&mut self)->Result<(),Error>{if self.peek()==Some(b'-'){self.p+=1}match self.peek(){Some(b'0')=>self.p+=1,Some(b'1'..=b'9')=>self.digits()?,_=>return Err(Error::Schema)}if self.peek()==Some(b'.'){self.p+=1;self.digits()?}if matches!(self.peek(),Some(b'e'|b'E')){self.p+=1;if matches!(self.peek(),Some(b'+'|b'-')){self.p+=1}self.digits()?}Ok(())}
 fn value(&mut self,depth:usize)->Result<Node,Error>{self.ws();self.n+=1;if depth>64||self.n>MAX_NODES{return Err(Error::Budget)}let start=self.p;let kind=match self.peek().ok_or(Error::Truncated)?{b'n'=>{self.literal("null")?;Kind::Null},b't'=>{self.literal("true")?;Kind::Bool(true)},b'f'=>{self.literal("false")?;Kind::Bool(false)},b'"'=>Kind::Str(self.string()?),b'-'|b'0'..=b'9'=>{self.number()?;Kind::Num},b'['=>{self.p+=1;self.ws();if self.peek()!=Some(b']'){loop{self.value(depth+1)?;self.ws();if self.peek()!=Some(b','){break}self.p+=1;}}self.eat(b']')?;Kind::Array},b'{'=>{self.p+=1;self.ws();let mut o=Vec::new();let mut keys=HashSet::new();if self.peek()!=Some(b'}'){loop{self.ws();let k=self.string()?;if !keys.insert(k.clone()){return Err(Error::Duplicate)}self.ws();self.eat(b':')?;let v=self.value(depth+1)?;o.push((k,v));self.ws();if self.peek()!=Some(b','){break}self.p+=1;}}self.eat(b'}')?;Kind::Object(o)},_=>return Err(Error::Schema)};Ok(Node{kind,span:start..self.p})}
}
fn guid(s:&str)->Result<[u8;16],Error>{if s.len()!=32||!s.bytes().all(|b|b.is_ascii_hexdigit()){return Err(Error::Schema)}let mut g=[0;16];for(i,c)in s.as_bytes().chunks_exact(2).enumerate(){g[i]=((c[0] as char).to_digit(16).unwrap()*16+(c[1] as char).to_digit(16).unwrap())as u8;}Ok(g)}
fn valid_date(s:&str)->bool{let b=s.as_bytes();if b.len()<20||b.len()>28||b[4]!=b'-'||b[7]!=b'-'||b[10]!=b'T'||b[13]!=b':'||b[16]!=b':'||*b.last().unwrap()!=b'Z'{return false}let n=|i:usize,j:usize|->Option<u32>{let x=b.get(i..j)?;if !x.iter().all(|c|c.is_ascii_digit()){return None}std::str::from_utf8(x).ok()?.parse().ok()};let (Some(y),Some(m),Some(d),Some(h),Some(mi),Some(sec))=(n(0,4),n(5,7),n(8,10),n(11,13),n(14,16),n(17,19))else{return false};let max=match m{1|3|5|7|8|10|12=>31,4|6|9|11=>30,2=>if y%4==0&&(y%100!=0||y%400==0){29}else{28},_=>return false};d>=1&&d<=max&&h<24&&mi<60&&sec<60&&(b.len()==20||(b.len()>=22&&b[19]==b'.'&&b[20..b.len()-1].iter().all(|c|c.is_ascii_digit())))}
pub fn read_account(bytes:&[u8])->Result<AccountIndex,Error>{if bytes.len()>MAX_ACCOUNT{return Err(Error::Budget)}let s=std::str::from_utf8(bytes).map_err(|_|Error::Schema)?;let mut p=Parser{s,p:0,n:0};let root=p.value(0)?;p.ws();if p.p!=s.len(){return Err(Error::Trailing)}let mut achievements=Vec::new();let mut counters=Vec::new();let mut seen=HashSet::new();for (g,r) in root.field("Achievements")?.obj()?{let guid=guid(g)?;if !seen.insert(guid){return Err(Error::Duplicate)}let a=r.field("IsComplete")?;let c=r.field("CurrentValue")?;let t=r.field("CompletedTime")?;let complete=match &a.kind{Kind::Bool(v)=>*v,_=>return Err(Error::Schema)};let current=c.number(s)?;if !(0.0..=3.402823466e38).contains(&current){return Err(Error::Schema)}let completed=match &t.kind{Kind::Null=>None,Kind::Str(v)if valid_date(v)=>Some(v.clone()),_=>return Err(Error::Schema)};if complete!=completed.is_some(){return Err(Error::Schema)}achievements.push(AccountAchievement{guid,complete,current,completed,fields:[a.span.clone(),c.span.clone(),t.span.clone()]});}seen.clear();for(g,r)in root.field("Counters")?.obj()?{let guid=guid(g)?;if !seen.insert(guid){return Err(Error::Duplicate)}let f=r.field("CurrentValue")?;counters.push(AccountCounter{guid,current:f.number(s)?,field:f.span.clone()});}Ok(AccountIndex{achievements,counters})}

/// Exact V33 root guard for the one supported Writer pair. Read-only token checks.
pub(crate) fn writer_root_guard(bytes:&[u8],root_guid:&str,counter_guid:&str,expected:u32)->Result<(),Error>{
 if bytes.len()>MAX_ACCOUNT{return Err(Error::Budget)}let s=std::str::from_utf8(bytes).map_err(|_|Error::Schema)?;let mut p=Parser{s,p:0,n:0};let root=p.value(0)?;p.ws();if p.p!=s.len(){return Err(Error::Trailing)}
 let a=root.field("Achievements")?.field(root_guid)?;let c=root.field("Counters")?.field(counter_guid)?;
 if !matches!(&a.field("IsComplete")?.kind,Kind::Bool(false))||!matches!(&a.field("CompletedTime")?.kind,Kind::Null)||a.field("CurrentValue")?.number(s)?!=expected as f64||c.field("CurrentValue")?.number(s)?!=expected as f64{return Err(Error::Schema)}
 for(k,v)in c.obj()?{if k=="CountedValues"&&!matches!(&v.kind,Kind::Null){return Err(Error::Schema)}if k=="CountedGuids"&&(!matches!(&v.kind,Kind::Array)||s[v.span.clone()].chars().filter(|c|!matches!(c,' '| '\t'|'\r'|'\n')).collect::<String>()!="[]"){return Err(Error::Schema)}}Ok(())
}
